def load() -> pd.DataFrame:
    import glob
    files = glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv')
    dfs = []
    for file in files:
        df = pd.read_csv(file, header=1)
        dfs.append(df)
    result = pd.concat(dfs, ignore_index=True)
    return result.dropna(how='all')

def process(clean_identity_theft_data, load_new_england_states) -> pd.DataFrame:
    ne_states = set(load_new_england_states['Name'].values)
    state_abbrev = {'Connecticut': 'CT', 'Maine': 'ME', 'Massachusetts': 'MA', 
                    'New Hampshire': 'NH', 'Rhode Island': 'RI', 'Vermont': 'VT'}
    ne_abbrev = set(state_abbrev[state] for state in ne_states)

    def has_ne_state(metro_name):
        for abbrev in ne_abbrev:
            if f', {abbrev}' in metro_name or f', {abbrev} ' in metro_name:
                return True
        return False

    filtered = clean_identity_theft_data[clean_identity_theft_data['Metropolitan_Area'].apply(has_ne_state)]
    return filtered.sort_values('Reports', ascending=False).reset_index(drop=True)
